async function foldArchive(chunks, initial, reduce) {
  const iterator = chunks[Symbol.asyncIterator]();
  const decoder = new TextDecoder();
  let state = initial;
  let physicalLine = 1;
  let recordIndex = 0;
  let pending = "";
  let completed = false;

  async function processLine(line) {
    if (line.endsWith("\r")) line = line.slice(0, -1);
    if (line.trim() === "") return false;

    let value;
    try {
      value = JSON.parse(line);
    } catch {
      return false;
    }

    const result = await reduce(state, value, {
      physicalLine,
      recordIndex
    });

    state = result.state;
    recordIndex += 1;
    return result.done === true;
  }

  async function consume(text) {
    pending += text;

    for (;;) {
      const newline = pending.indexOf("\n");
      if (newline === -1) return false;

      const line = pending.slice(0, newline);
      pending = pending.slice(newline + 1);

      const done = await processLine(line);
      physicalLine += 1;

      if (done) return true;
    }
  }

  try {
    for (;;) {
      const step = await iterator.next();

      if (step.done) break;

      if (await consume(decoder.decode(step.value, { stream: true }))) {
        return state;
      }
    }

    if (await consume(decoder.decode())) {
      return state;
    }

    if (pending !== "") {
      if (await processLine(pending)) {
        return state;
      }
    }

    completed = true;
    return state;
  } finally {
    if (!completed && typeof iterator.return === "function") {
      try {
        await iterator.return();
      } catch {}
    }
  }
}
